<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal" @submit.prevent="submit"><div class="modal-head"><div><h2>{{task?'Editar tarefa':'Nova tarefa'}}</h2><p>Organize uma entrega do workspace.</p></div><button type="button" @click="$emit('close')"><X/></button></div><label>Título<input v-model="form.title" required/></label><label class="description-label">Descrição<textarea v-model="form.description" required/></label><div class="modal-fields"><label>Projeto<select v-model.number="form.projectId" :disabled="!admin"><option v-for="p in projects" :value="p.id">{{p.name}}</option></select></label><label>Responsável<select v-model.number="form.assigneeId" :disabled="!admin"><option v-for="m in members" :value="m.id">{{m.name}} — {{m.job}}</option></select></label><label>Prioridade<select v-model="form.priority" :disabled="!admin"><option>Alta</option><option>Média</option><option>Baixa</option></select></label><label>Status<select v-model="form.status"><option>Pendente</option><option>Em andamento</option><option>Concluída</option></select></label><label>Prazo<input v-model="form.due" type="date" :disabled="!admin"/></label></div><div class="modal-actions"><button v-if="task&&admin" type="button" class="delete-btn" @click="$emit('remove',task.id)"><Trash2/>Excluir</button><span/><button type="button" class="cancel" @click="$emit('close')">Cancelar</button><button class="primary-btn"><Check/>Salvar</button></div></form></div></template>
<script setup lang="ts">import{reactive}from"vue";import{Check,Trash2,X}from"lucide-vue-next";import type{Member,Project,Task}from"../stores/taskflow";const props=defineProps<{task?:Task;projectId:number;projects:Project[];members:Member[];admin:boolean;memberId:number}>(),emit=defineEmits(["close","save","remove"]),form=reactive<Task>(props.task?{...props.task}:{id:Date.now(),title:"",description:"",projectId:props.projectId,assigneeId:props.memberId,priority:"Média",status:"Pendente",due:new Date().toISOString().slice(0,10)});function submit(){emit("save",{...form})}</script>
